<script setup lang="ts">
import { Link, useForm } from '@inertiajs/vue3';
import { Plus, Trash2 } from '@lucide/vue';
import { computed, watch } from 'vue';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
type Supplier = { person_id: string; name: string; payment_term_days: number }; type Presentation = { id: string; name: string; sku: string; unit: string }; type Option = { value: string; label: string };
const props = defineProps<{ suppliers: Supplier[]; presentations: Presentation[]; paymentConditions: Option[]; today: string }>();
const form = useForm({ supplier_person_id: '', supplier_document_number: '', issued_at: props.today, due_at: '', payment_condition: 'cash', additional_costs: 0, notes: '', lines: [{ presentation_id: '', quantity: 1, unit_price: 0 }] });
const money = (value: number) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 }).format(value || 0);
const subtotal = computed(() => form.lines.reduce((sum, line) => sum + Number(line.quantity || 0) * Number(line.unit_price || 0), 0)); const total = computed(() => subtotal.value + Number(form.additional_costs || 0));
const addLine = () => form.lines.push({ presentation_id: '', quantity: 1, unit_price: 0 }); const removeLine = (index: number) => form.lines.length > 1 && form.lines.splice(index, 1);
watch(() => form.supplier_person_id, (id) => { const supplier = props.suppliers.find((item) => item.person_id === id); if (supplier && form.payment_condition === 'credit') { const due = new Date(`${form.issued_at}T12:00:00`); due.setDate(due.getDate() + supplier.payment_term_days); form.due_at = due.toISOString().slice(0, 10); } });
watch(() => form.payment_condition, (condition) => { if (condition === 'cash') form.due_at = ''; });
</script>
<template><form class="grid gap-6" @submit.prevent="form.post('/purchasing/purchases')"><section class="grid gap-4 md:grid-cols-2 lg:grid-cols-3"><div class="grid gap-2"><Label>Proveedor</Label><select v-model="form.supplier_person_id" required class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="" disabled>Selecciona</option><option v-for="supplier in suppliers" :key="supplier.person_id" :value="supplier.person_id">{{ supplier.name }}</option></select><p v-if="form.errors.supplier_person_id" class="text-sm text-destructive">{{ form.errors.supplier_person_id }}</p></div><div class="grid gap-2"><Label>Factura del proveedor</Label><Input v-model="form.supplier_document_number" /></div><div class="grid gap-2"><Label>Fecha de compra</Label><Input v-model="form.issued_at" type="date" required /></div><div class="grid gap-2"><Label>Condición</Label><select v-model="form.payment_condition" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="option in paymentConditions" :key="option.value" :value="option.value">{{ option.label }}</option></select></div><div v-if="form.payment_condition === 'credit'" class="grid gap-2"><Label>Vencimiento</Label><Input v-model="form.due_at" type="date" required /><p v-if="form.errors.due_at" class="text-sm text-destructive">{{ form.errors.due_at }}</p></div><div class="grid gap-2"><Label>Costos adicionales / transporte</Label><Input v-model.number="form.additional_costs" type="number" min="0" required /></div></section><section class="grid gap-3"><div class="flex items-center justify-between"><div><h2 class="font-semibold">Artículos comprados</h2><p class="text-xs text-muted-foreground">El costo adicional se distribuye proporcionalmente.</p></div><Button type="button" variant="outline" size="sm" @click="addLine"><Plus /> Línea</Button></div><div v-for="(line, index) in form.lines" :key="index" class="grid items-end gap-3 rounded-lg border p-3 md:grid-cols-[minmax(0,1fr)_10rem_11rem_auto]"><div class="grid gap-2"><Label>Presentación</Label><select v-model="line.presentation_id" required class="h-9 min-w-0 rounded-md border bg-transparent px-3 text-sm"><option value="" disabled>Selecciona</option><option v-for="presentation in presentations" :key="presentation.id" :value="presentation.id">{{ presentation.name }} ({{ presentation.unit }})</option></select></div><div class="grid gap-2"><Label>Cantidad</Label><Input v-model.number="line.quantity" type="number" min="0.000001" step="0.000001" required /></div><div class="grid gap-2"><Label>Precio unitario COP</Label><Input v-model.number="line.unit_price" type="number" min="0" required /></div><Button type="button" variant="ghost" size="icon" :disabled="form.lines.length === 1" @click="removeLine(index)"><Trash2 /></Button><p v-if="form.errors[`lines.${index}.presentation_id`]" class="text-sm text-destructive md:col-span-4">{{ form.errors[`lines.${index}.presentation_id`] }}</p></div></section><div class="grid gap-2"><Label>Notas</Label><textarea v-model="form.notes" rows="3" class="rounded-md border bg-transparent px-3 py-2 text-sm" /></div><section class="ml-auto grid w-full max-w-sm gap-1 rounded-lg bg-muted/40 p-4 text-sm"><div class="flex justify-between"><span>Subtotal</span><strong>{{ money(subtotal) }}</strong></div><div class="flex justify-between"><span>Costos adicionales</span><strong>{{ money(form.additional_costs) }}</strong></div><div class="flex justify-between border-t pt-2 text-base"><span>Total</span><strong>{{ money(total) }}</strong></div></section><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link href="/purchasing/purchases">Cancelar</Link></Button><Button type="submit" :disabled="form.processing">Confirmar compra</Button></div></form></template>
